#include <stdio.h>

int main(void) {
    int a[] = {2, 4, 6, 8, 10};
    int *p = a;
    int sum = 0;

    for(int i = 0; i < 3; i++) {
        sum += *(p + i);
        *(a + i) += *(a + i + 1);
    }

    printf("%d", sum);
    return 0;
}

